pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testRegression_property() public {
        address alice = address(0x123);
        vm.deal(alice, 20 ether);

        vm.prank(alice);
        (bool ok1,) = address(c).call{value: 10 ether}("");
        assertTrue(ok1);

        uint pastAfterFirst = c.pastBlockTime();

        vm.prank(alice);
        (bool ok2,) = address(c).call{value: 10 ether}("");

        assertTrue(!ok2);
    }
}
